// ── Server -> client requests ───────────────────────────────────────────────────
#[derive(Debug, Clone)]
pub enum ServerRequestPayload {
    /// A dangerous command awaits the user's decision.
    Approval(ApprovalRequestParams),
    /// The clarify tool: ask the user 1-5 questions.
    Clarify(ClarifyRequestParams),
    /// Masked sudo password for the Bot Screen package install; app-level (empty session).
    DisplayInstallSudo(DisplayInstallSudoParams),
    /// Click / type / scroll / annotate inside the in-app browser preview.
    PreviewAct(PreviewActRequestParams),
    /// Read the in-app browser preview's text (JSON text answer).
    PreviewRead(ReadRangeRequestParams),
    /// Masked value for a named env var (skills / setup flows).
    Secret(SecretRequestParams),
    /// The onboarding chat's card for one beat; blocks setup_beat until answered (300 s).
    SetupBeat(SetupBeatRequestParams),
    /// Masked sudo password for the terminal tool.
    Sudo(SudoRequestParams),
    /// Read the visible in-app terminal buffer (JSON text answer).
    TerminalRead(ReadRangeRequestParams),
    /// Apply set_theme values in the window showing the session (JSON text answer).
    ThemeApply(ThemeApplyRequestParams),
    /// Show an accent or layout picker card in the chat and wait for the pick.
    ThemePick(ThemePickRequestParams),
    /// Drive a guided tour highlight in the desktop renderer.
    Tour(TourRequestParams),
    /// A one-time / 2FA code the user reads from their device.
    VaultCode(VaultCodeRequestParams),
    /// Save a login for a site the agent is about to fill; the answer is JSON {identifier, password}.
    VaultSaveLogin(VaultSaveLoginRequestParams),
    /// Master password to unlock an external password manager for this session.
    VaultUnlockPrompt(VaultUnlockRequestParams),
    /// Enumerate the native window below the app (JSON text answer).
    WindowRead(EmptyRequestParams),
    Unknown { method: String, params: serde_json::Value },
}

impl ServerRequestPayload {
    pub fn parse(method: &str, params: serde_json::Value) -> Result<Self, serde_json::Error> {
        match method {
            "approval" => Ok(Self::Approval(serde_json::from_value(params)?)),
            "clarify" => Ok(Self::Clarify(serde_json::from_value(params)?)),
            "display.install.sudo" => Ok(Self::DisplayInstallSudo(serde_json::from_value(params)?)),
            "preview.act" => Ok(Self::PreviewAct(serde_json::from_value(params)?)),
            "preview.read" => Ok(Self::PreviewRead(serde_json::from_value(params)?)),
            "secret" => Ok(Self::Secret(serde_json::from_value(params)?)),
            "setup_beat" => Ok(Self::SetupBeat(serde_json::from_value(params)?)),
            "sudo" => Ok(Self::Sudo(serde_json::from_value(params)?)),
            "terminal.read" => Ok(Self::TerminalRead(serde_json::from_value(params)?)),
            "theme.apply" => Ok(Self::ThemeApply(serde_json::from_value(params)?)),
            "theme.pick" => Ok(Self::ThemePick(serde_json::from_value(params)?)),
            "tour" => Ok(Self::Tour(serde_json::from_value(params)?)),
            "vault.code" => Ok(Self::VaultCode(serde_json::from_value(params)?)),
            "vault.save_login" => Ok(Self::VaultSaveLogin(serde_json::from_value(params)?)),
            "vault.unlock_prompt" => Ok(Self::VaultUnlockPrompt(serde_json::from_value(params)?)),
            "window.read" => Ok(Self::WindowRead(serde_json::from_value(params)?)),
            other => Ok(Self::Unknown { method: other.to_string(), params }),
        }
    }
}

// ── Server -> client notifications ──────────────────────────────────────────────
#[derive(Debug, Clone)]
pub enum GatewayNotification {
    /// A status line the agent printed during a local viewer's turn.
    AgentPrint(AgentPrintPayload),
    /// Output chunk from an agent-owned background process.
    AgentTerminalOutput(TerminalOutputPayload),
    /// Pending gateway approvals were dropped by interrupt/reap/teardown; the wait resolved as deny (not a user refusal).
    ApprovalCancelled(ApprovalCancelledPayload),
    /// A /background side agent finished.
    BackgroundComplete(SideAgentCompletePayload),
    /// Device-flow URL + code for the billing scope step-up; the client opens the browser.
    BillingStepUpVerification(BillingStepUpVerificationPayload),
    /// A bot-relay outbox envelope is queued; drain it.
    BotRelayOutboxPending(ChangeSignalPayload),
    /// Browser (CDP) connect / install progress line.
    BrowserProgress(BrowserProgressPayload),
    /// A /btw side question was answered.
    BtwComplete(SideAgentCompletePayload),
    /// A connection operation opened on this session; the desktop renders its card.
    ConnectionRequest(ConnectionRequestPayload),
    /// One transition or the settlement of an open connection operation.
    ConnectionUpdate(ConnectionUpdatePayload),
    /// cron/jobs.json moved; refetch the cron list.
    CronChanged(ChangeSignalPayload),
    /// The install ended (0 ok, -1 cancelled, -2 no sudo: the command to run by hand was streamed).
    DisplayInstallDone(DisplayInstallDonePayload),
    /// One line of package-manager output.
    DisplayInstallLog(DisplayInstallLogPayload),
    /// The takeover lease changed hands; every client repaints.
    DisplayLease(DisplayLeasePayload),
    /// This profile's screen started or stopped (also for transitions made outside hermes serve).
    DisplayStatus(DisplayStatusPayload),
    /// A session-level failure outside a turn (agent init, model switch, compression, resume).
    Error(ErrorPayload),
    /// The account service wants a browser challenge cleared before the free-tier token exchange (broadcast); the desktop loads ``url`` in a hidden window.
    FreeTierChallenge(FreeTierChallengePayload),
    /// First frame of a connection: the resolved skin, the change-event capability and the replay epoch.
    GatewayReady(GatewayReadyPayload),
    /// A Group Chat log, task or live status moved; an open room re-reads its log delta and groups.state.
    GroupsChanged(GroupsChangedPayload),
    /// The turn ended: final text, usage and outcome.
    MessageComplete(MessageCompletePayload),
    /// One streamed chunk of the assistant reply (null text: segment boundary).
    MessageDelta(MessageDeltaPayload),
    /// Interim assistant commentary (text beside tool calls) sealed as its own segment.
    MessageInterim(MessageInterimPayload),
    /// The agent reacted to a message; paint it live.
    MessageReaction(MessageReactionPayload),
    /// A turn began streaming; an automation turn carries its async-result card.
    MessageStart(MessageStartPayload),
    /// The MoA aggregator started.
    MoaAggregating(MoaAggregatingPayload),
    /// MoA phase transition (currently only ``aggregator``).
    MoaPhase(MoaPhasePayload),
    /// MoA reference fan-out progress (n/total).
    MoaProgress(MoaProgressPayload),
    /// One MoA reference model's output.
    MoaReference(MoaReferencePayload),
    /// Informational one-liner for the session (capabilities refreshed).
    Notice(NoticePayload),
    /// Withdraw the notice with this key.
    NotificationClear(NotificationClearPayload),
    /// Show / replace a keyed out-of-band notice (toast or status bar).
    NotificationShow(NotificationShowPayload),
    /// A first-run onboarding run ended; sent to every connected window.
    OnboardingEnded(OnboardingEndedPayload),
    /// Pairing state moved; refetch pairing.
    PairingChanged(ChangeSignalPayload),
    /// Focus / reveal a named desktop pane.
    PaneReveal(PaneRevealPayload),
    /// The active pet / its spritesheet changed (watcher).
    PetChanged(PetChangedPayload),
    /// Pet base-draft generation progress.
    PetGenerateProgress(PetGenerateProgressPayload),
    /// Pet hatch (row drawing) progress.
    PetHatchProgress(PetHatchProgressPayload),
    /// gateway_state.json moved; refetch platform status.
    PlatformsChanged(ChangeSignalPayload),
    /// Close the preview pane or one tab.
    PreviewClose(PreviewClosePayload),
    /// Open a URL / file in the desktop preview pane.
    PreviewOpen(PreviewOpenPayload),
    /// The hidden preview-restart agent finished.
    PreviewRestartComplete(SideAgentCompletePayload),
    /// Progress line from the preview-restart agent.
    PreviewRestartProgress(PreviewRestartProgressPayload),
    /// projects.db moved; refetch the project list + tree.
    ProjectsChanged(ChangeSignalPayload),
    /// Affection reaction detected in the user's message (hearts etc.).
    Reaction(ReactionPayload),
    /// A completed reasoning block (non-streaming providers).
    ReasoningAvailable(StreamDeltaPayload),
    /// One streamed chunk of the model's reasoning.
    ReasoningDelta(StreamDeltaPayload),
    /// The backend withdrew an open server→client request; clear the matching card only.
    RequestCancel(RequestCancelPayload),
    /// Background review of the last turn finished.
    ReviewSummary(ReviewSummaryPayload),
    /// Persisted goal / loop / heartbeat state changed.
    SessionControlUpdate(SessionControlUpdatePayload),
    /// Live session settings snapshot (``server._session_info``); also the ``info`` of create/resume/activate.
    SessionInfo(SessionLiveInfo),
    /// The backend reclaimed a live session out from under its clients.
    SessionReclaimed(SessionReclaimedPayload),
    /// Deferred resume hydration progress.
    SessionResumeProgress(SessionResumeProgressPayload),
    /// Auto-titling renamed the session (``session_id`` is the stored key).
    SessionTitle(SessionTitlePayload),
    /// Mid-turn usage tick; message.complete carries the authoritative final usage.
    SessionUsage(SessionUsagePayload),
    /// state.db moved; refetch the session list.
    SessionsChanged(ChangeSignalPayload),
    /// The free-tier bootstrap finished (broadcast); the desktop's setup gate reads the record.
    SetupReady(SetupReadyPayload),
    /// A skill root moved (installed/removed elsewhere); refetch commands.catalog from the gateway.
    SkillsChanged(ChangeSignalPayload),
    /// The active skin moved (name switch or live colour edit); repaint from this palette.
    SkinChanged(SkinPayload),
    /// Transient status line (kind: status, lifecycle, compacting, goal, loop, heartbeat, process, …).
    StatusUpdate(StatusUpdatePayload),
    /// A child finished (status + observability rollup).
    SubagentComplete(SubagentEventPayload),
    /// Batched tool-name progress from a child.
    SubagentProgress(SubagentEventPayload),
    /// delegate_task accepted a child goal (before the child starts).
    SubagentSpawnRequested(SubagentEventPayload),
    /// A delegated child started running.
    SubagentStart(SubagentEventPayload),
    /// A child's reasoning chunk.
    SubagentThinking(SubagentEventPayload),
    /// A child called a tool.
    SubagentTool(SubagentEventPayload),
    /// An agent-owned background process closed.
    TerminalClose(TerminalClosePayload),
    /// Legacy thinking-text chunk (thinking_callback).
    ThinkingDelta(StreamDeltaPayload),
    /// Point at a desktop element with a one-line tip bubble.
    TipShow(TipShowPayload),
    /// Full todo snapshot after a todo tool ran.
    TodoUpdated(TodoUpdatedPayload),
    /// A tool call finished: parsed result, summary, optional diff / todo snapshot.
    ToolComplete(ToolCompletePayload),
    /// The model is emitting a tool call's arguments.
    ToolGenerating(ToolGeneratingPayload),
    /// Tool output was classified as risky (prompt-injection / secret findings).
    ToolOutputRisk(ToolOutputRiskPayload),
    /// Live progress of a running tool call (MCP notifications/progress).
    ToolProgress(ToolProgressPayload),
    /// A tool call began (stable id + full args).
    ToolStart(ToolStartPayload),
    /// Barge-in: the spoken interjection interrupted the turn; no payload.
    VoiceInterrupted(serde_json::Value),
    /// Live STT text so far while the user is still speaking.
    VoicePartial(VoicePartialPayload),
    /// Voice recorder state changed.
    VoiceStatus(VoiceStatusPayload),
    /// A voice capture produced text (or a stop phrase / silence limit).
    VoiceTranscript(VoiceTranscriptPayload),
    /// A wake phrase fired.
    WakeDetected(WakeDetectedPayload),
    Unknown { event_type: String, payload: serde_json::Value },
}

impl GatewayNotification {
    pub fn parse(event_type: &str, payload: serde_json::Value) -> Result<Self, serde_json::Error> {
        match event_type {
            "agent.print" => Ok(Self::AgentPrint(serde_json::from_value(payload)?)),
            "agent.terminal.output" => Ok(Self::AgentTerminalOutput(serde_json::from_value(payload)?)),
            "approval.cancelled" => Ok(Self::ApprovalCancelled(serde_json::from_value(payload)?)),
            "background.complete" => Ok(Self::BackgroundComplete(serde_json::from_value(payload)?)),
            "billing.step_up.verification" => Ok(Self::BillingStepUpVerification(serde_json::from_value(payload)?)),
            "bot_relay.outbox.pending" => Ok(Self::BotRelayOutboxPending(serde_json::from_value(payload)?)),
            "browser.progress" => Ok(Self::BrowserProgress(serde_json::from_value(payload)?)),
            "btw.complete" => Ok(Self::BtwComplete(serde_json::from_value(payload)?)),
            "connection.request" => Ok(Self::ConnectionRequest(serde_json::from_value(payload)?)),
            "connection.update" => Ok(Self::ConnectionUpdate(serde_json::from_value(payload)?)),
            "cron.changed" => Ok(Self::CronChanged(serde_json::from_value(payload)?)),
            "display.install.done" => Ok(Self::DisplayInstallDone(serde_json::from_value(payload)?)),
            "display.install.log" => Ok(Self::DisplayInstallLog(serde_json::from_value(payload)?)),
            "display.lease" => Ok(Self::DisplayLease(serde_json::from_value(payload)?)),
            "display.status" => Ok(Self::DisplayStatus(serde_json::from_value(payload)?)),
            "error" => Ok(Self::Error(serde_json::from_value(payload)?)),
            "free_tier.challenge" => Ok(Self::FreeTierChallenge(serde_json::from_value(payload)?)),
            "gateway.ready" => Ok(Self::GatewayReady(serde_json::from_value(payload)?)),
            "groups.changed" => Ok(Self::GroupsChanged(serde_json::from_value(payload)?)),
            "message.complete" => Ok(Self::MessageComplete(serde_json::from_value(payload)?)),
            "message.delta" => Ok(Self::MessageDelta(serde_json::from_value(payload)?)),
            "message.interim" => Ok(Self::MessageInterim(serde_json::from_value(payload)?)),
            "message.reaction" => Ok(Self::MessageReaction(serde_json::from_value(payload)?)),
            "message.start" => Ok(Self::MessageStart(serde_json::from_value(payload)?)),
            "moa.aggregating" => Ok(Self::MoaAggregating(serde_json::from_value(payload)?)),
            "moa.phase" => Ok(Self::MoaPhase(serde_json::from_value(payload)?)),
            "moa.progress" => Ok(Self::MoaProgress(serde_json::from_value(payload)?)),
            "moa.reference" => Ok(Self::MoaReference(serde_json::from_value(payload)?)),
            "notice" => Ok(Self::Notice(serde_json::from_value(payload)?)),
            "notification.clear" => Ok(Self::NotificationClear(serde_json::from_value(payload)?)),
            "notification.show" => Ok(Self::NotificationShow(serde_json::from_value(payload)?)),
            "onboarding.ended" => Ok(Self::OnboardingEnded(serde_json::from_value(payload)?)),
            "pairing.changed" => Ok(Self::PairingChanged(serde_json::from_value(payload)?)),
            "pane.reveal" => Ok(Self::PaneReveal(serde_json::from_value(payload)?)),
            "pet.changed" => Ok(Self::PetChanged(serde_json::from_value(payload)?)),
            "pet.generate.progress" => Ok(Self::PetGenerateProgress(serde_json::from_value(payload)?)),
            "pet.hatch.progress" => Ok(Self::PetHatchProgress(serde_json::from_value(payload)?)),
            "platforms.changed" => Ok(Self::PlatformsChanged(serde_json::from_value(payload)?)),
            "preview.close" => Ok(Self::PreviewClose(serde_json::from_value(payload)?)),
            "preview.open" => Ok(Self::PreviewOpen(serde_json::from_value(payload)?)),
            "preview.restart.complete" => Ok(Self::PreviewRestartComplete(serde_json::from_value(payload)?)),
            "preview.restart.progress" => Ok(Self::PreviewRestartProgress(serde_json::from_value(payload)?)),
            "projects.changed" => Ok(Self::ProjectsChanged(serde_json::from_value(payload)?)),
            "reaction" => Ok(Self::Reaction(serde_json::from_value(payload)?)),
            "reasoning.available" => Ok(Self::ReasoningAvailable(serde_json::from_value(payload)?)),
            "reasoning.delta" => Ok(Self::ReasoningDelta(serde_json::from_value(payload)?)),
            "request.cancel" => Ok(Self::RequestCancel(serde_json::from_value(payload)?)),
            "review.summary" => Ok(Self::ReviewSummary(serde_json::from_value(payload)?)),
            "session.control.update" => Ok(Self::SessionControlUpdate(serde_json::from_value(payload)?)),
            "session.info" => Ok(Self::SessionInfo(serde_json::from_value(payload)?)),
            "session.reclaimed" => Ok(Self::SessionReclaimed(serde_json::from_value(payload)?)),
            "session.resume_progress" => Ok(Self::SessionResumeProgress(serde_json::from_value(payload)?)),
            "session.title" => Ok(Self::SessionTitle(serde_json::from_value(payload)?)),
            "session.usage" => Ok(Self::SessionUsage(serde_json::from_value(payload)?)),
            "sessions.changed" => Ok(Self::SessionsChanged(serde_json::from_value(payload)?)),
            "setup.ready" => Ok(Self::SetupReady(serde_json::from_value(payload)?)),
            "skills.changed" => Ok(Self::SkillsChanged(serde_json::from_value(payload)?)),
            "skin.changed" => Ok(Self::SkinChanged(serde_json::from_value(payload)?)),
            "status.update" => Ok(Self::StatusUpdate(serde_json::from_value(payload)?)),
            "subagent.complete" => Ok(Self::SubagentComplete(serde_json::from_value(payload)?)),
            "subagent.progress" => Ok(Self::SubagentProgress(serde_json::from_value(payload)?)),
            "subagent.spawn_requested" => Ok(Self::SubagentSpawnRequested(serde_json::from_value(payload)?)),
            "subagent.start" => Ok(Self::SubagentStart(serde_json::from_value(payload)?)),
            "subagent.thinking" => Ok(Self::SubagentThinking(serde_json::from_value(payload)?)),
            "subagent.tool" => Ok(Self::SubagentTool(serde_json::from_value(payload)?)),
            "terminal.close" => Ok(Self::TerminalClose(serde_json::from_value(payload)?)),
            "thinking.delta" => Ok(Self::ThinkingDelta(serde_json::from_value(payload)?)),
            "tip.show" => Ok(Self::TipShow(serde_json::from_value(payload)?)),
            "todo.updated" => Ok(Self::TodoUpdated(serde_json::from_value(payload)?)),
            "tool.complete" => Ok(Self::ToolComplete(serde_json::from_value(payload)?)),
            "tool.generating" => Ok(Self::ToolGenerating(serde_json::from_value(payload)?)),
            "tool.output_risk" => Ok(Self::ToolOutputRisk(serde_json::from_value(payload)?)),
            "tool.progress" => Ok(Self::ToolProgress(serde_json::from_value(payload)?)),
            "tool.start" => Ok(Self::ToolStart(serde_json::from_value(payload)?)),
            "voice.interrupted" => Ok(Self::VoiceInterrupted(serde_json::from_value(payload)?)),
            "voice.partial" => Ok(Self::VoicePartial(serde_json::from_value(payload)?)),
            "voice.status" => Ok(Self::VoiceStatus(serde_json::from_value(payload)?)),
            "voice.transcript" => Ok(Self::VoiceTranscript(serde_json::from_value(payload)?)),
            "wake.detected" => Ok(Self::WakeDetected(serde_json::from_value(payload)?)),
            other => Ok(Self::Unknown { event_type: other.to_string(), payload }),
        }
    }
}
